      "code": "window.__pbReg = window.__pbReg || { intervals: [], timeouts: [], frames: [] };\n(function () {\n  var reg = window.__pbReg;\n  var setInterval = function (fn, ms) { var id = window.setInterval(fn, ms); reg.intervals.push(id); return id; };\n  var clearInterval = function (id) { reg.intervals = reg.intervals.filter(function (x) { return x !== id; }); return window.clearInterval(id); };\n  var setTimeout = function (fn, ms) { var args = Array.prototype.slice.call(arguments, 2); var id = window.setTimeout(function () { fn.apply(null, args); }, ms); reg.timeouts.push(id); return id; };\n  var clearTimeout = function (id) { reg.timeouts = reg.timeouts.filter(function (x) { return x !== id; }); return window.clearTimeout(id); };\n  var requestAnimationFrame = function (fn) { var id = window.requestAnimationFrame(fn); reg.frames.push(id); return id; };\n  var cancelAnimationFrame = function (id) { reg.frames = reg.frames.filter(function (x) { return x !== id; }); return window.cancelAnimationFrame(id); };\n\nfunction __pbAfterLoad(type, fn, opts) {\n  if (document.readyState === \"complete\") { try { fn(); } catch (error) { console.error(error); } }\n  else { window.addEventListener(type, fn, opts); }\n}\n\nconst toast=(s)=>{const el=document.getElementById('toast');el.textContent=s;el.classList.add('on');clearTimeout(window._tt);window._tt=setTimeout(()=>el.classList.remove('on'),2400)};\nconst adminNav=document.getElementById('adminNav'),navToggle=document.getElementById('navToggle');\nnavToggle.addEventListener('click',()=>{const hidden=adminNav.classList.toggle('is-collapsed');const open=!hidden;navToggle.setAttribute('aria-expanded',String(open));navToggle.setAttribute('aria-label',open?'Collapse navigation':'Expand navigation');navToggle.title=open?'Collapse navigation':'Expand navigation';adminNav.setAttribute('aria-hidden',String(hidden));adminNav.classList.toggle('is-open',open)});\nconst themeToggle=document.getElementById('themeToggle'),themeLabel=document.getElementById('themeLabel');\nfunction setAdminTheme(theme){document.documentElement.dataset.theme=theme;const dark=theme==='dark';themeToggle.setAttribute('aria-pressed',String(dark));themeToggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');themeLabel.textContent=dark?'Dark':'Light';themeToggle.firstChild.textContent=dark?'☾ ':'☀ ';try{localStorage.setItem('prometheus-theme',theme)}catch(e){}}\nlet adminTheme='dark';try{adminTheme=localStorage.getItem('prometheus-theme')||'dark'}catch(e){}setAdminTheme(adminTheme);\nthemeToggle.addEventListener('click',()=>setAdminTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));\ndocument.getElementById('poolFilters').addEventListener('click',e=>{const b=e.target.closest('button[data-filter]');if(!b)return;document.querySelectorAll('#poolFilters button').forEach(x=>x.classList.toggle('on',x===b));document.querySelectorAll('#poolRows tr').forEach(r=>r.hidden=b.dataset.filter==='watch'?r.dataset.state!=='watch':b.dataset.filter==='paused'?r.dataset.state!=='paused':false)});\ndocument.getElementById('poolRows').addEventListener('click',e=>{const b=e.target.closest('[data-pool]');if(b)toast(b.dataset.pool+' operations opened · demo mode')});\ndocument.getElementById('createPool').onclick=()=>toast('Pool creation flow · demo preview');document.getElementById('editTiers').onclick=()=>toast('Tier policy editor · governance preview');document.getElementById('reviewChanges').onclick=()=>toast('Governance policy review · demo preview');\n\n})();"
